export interface ReviewEscalationReport {
  schemaVersion: 'lattice.review_escalation_status.v1';
  ok: boolean;
  required: boolean;
  trigger: {
    firstReviewRound: string | null;
    requiredProblemCount: number;
    countableProblems: CountableFirstRoundProblem[];
    ignoredCount: number;
    explicitHighRiskPolicy: ReviewEscalationExplicitHighRiskPolicyStatus;
  };
  materialHash: string | null;
  storyFilesHash: string | null;
  advisories?: string[];
  fullQuorum: {
    requiredRounds: number;
    requiredPassingHostsPerRound: number;
    ok: boolean;
    validRounds: HostVerdictRound[];
    invalidRounds: HostVerdictRound[];
    ignoredVerdicts: IgnoredHostVerdict[];
  };
  degradedFallback: {
    ok: boolean;
    allowed: boolean;
    record: ReviewEscalationFallbackRecord | null;
    requiredRounds: number;
    requiredPassingHostsPerRound: number;
    validRounds: HostVerdictRound[];
    invalidRounds: HostVerdictRound[];
    ignoredVerdicts: IgnoredHostVerdict[];
  seeds: KeywordSeedsArtifact;
  execute: CandidateHostExecutor;
  minimumPrimaryOverlap?: number;
}): Promise<{ attempts: HostProposalAttempt[]; accepted: HostKeywordProposal[]; sanitizedDigest: string; hostDisagreement: boolean }> {
  const sanitized = sanitizeHostPayload(args.payload);
  if (!sanitized.safe) {
    return {
      attempts: [
        { host: 'codex-cli', status: 'skipped-unsafe', proposal: null, reason: sanitized.reason },
        { host: 'claude-cli', status: 'skipped-unsafe', proposal: null, reason: sanitized.reason },
      ],
      accepted: [],
      sanitizedDigest: sanitized.digest,
      hostDisagreement: false,
    };
  }
  const run = async (host: HostKeywordProposal['host']): Promise<HostProposalAttempt> => {
    const promptDigest = digestCandidateRoutingValue({ host, payload: sanitized.value, seedDigest: args.seeds.seedDigest });
    try {
      const raw = await args.execute({ host, storyId: args.storyId, sanitizedPayload: sanitized.value, promptDigest, seedDigest: args.seeds.seedDigest });
      const proposal = normalizeHostProposal(raw, { storyId: args.storyId, host, seedDigest: args.seeds.seedDigest });
      if (proposal.promptDigest !== promptDigest) throw new Error('host proposal prompt digest mismatch');
      return { host, status: 'accepted', proposal, reason: null };
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      const lower = message.toLowerCase();
      const status: HostProposalAttempt['status'] = lower.includes('timeout')
        ? 'timeout'
        : lower.includes('quota') || lower.includes('rate limit')
          ? 'quota-limited'
          : lower.includes('unavailable') || lower.includes('enoent')
            ? 'unavailable'
            : 'rejected';
      return { host, status, proposal: null, reason: message.slice(0, 240) };
    }
  };
  // Promise.all preserves input order. Never let host latency determine proposal,
  // query-group, candidate, or artifact ordering.
  const attempts = await Promise.all([run('codex-cli'), run('claude-cli')]);
  const primary = attempts.flatMap(attempt => attempt.proposal ? [attempt.proposal] : []);
  const minimumOverlap = args.minimumPrimaryOverlap ?? 0.2;
  const disagree = primary.length === 2 && proposalOverlap(primary[0], primary[1]) < minimumOverlap;
  const accepted = attempts.flatMap(attempt => attempt.proposal ? [attempt.proposal] : []);
  return { attempts, accepted, sanitizedDigest: sanitized.digest, hostDisagreement: disagree };
}

function searchable(entry: CorpusIndexEntry, body: string): string {
  return `${entry.path}\n${entry.headings.join('\n')}\n${body}`.toLowerCase();
}

function orderedQueryTerms(seeds: KeywordSeed[], proposals: HostKeywordProposal[] = []): string[] {
  const terms = [...seeds.filter(seed => seed.source !== 'relatedDoc').map(seed => seed.normalized), ...proposals.flatMap(proposal => proposal.terms.map(term => normalizeKeyword(term.term)))]
    .filter(term => term.length >= 3);
  return [...new Set(terms)];
}

function queryGroupsFromTerms(unique: string[], budget: number): string[][] {
  const groups = unique.slice(0, budget).map(term => [term]);
  if (unique.length >= 2 && groups.length < budget) groups.push([unique[0], unique[1]]);
  return groups.slice(0, budget);
}

export function buildQueryGroups(seeds: KeywordSeed[], proposals: HostKeywordProposal[] = [], budget = DEFAULT_QUERY_GROUP_BUDGET): string[][] {
  return queryGroupsFromTerms(orderedQueryTerms(seeds, proposals), budget);
}

export function routeCandidateSpecs(args: {
  projectRoot: string;
  storyId: string;
  corpus: CorpusIndexArtifact;
  seeds: KeywordSeedsArtifact;
export function createCandidateSpecRoutingHandlers(
  ctx: HandlerContext,
  options: { executeHost?: CandidateHostExecutor; resolveReadiness?: CandidateReadinessResolver } = {},
) {
  return {
    async candidate_spec_route(args: CandidateSpecRouteArgs): Promise<CandidateSpecSetArtifact | string> {
      const story = ctx.store.readStory(args.storyId);
      const config = loadConfig(ctx.root);
      const input = currentStoryRoutingInput(ctx, args.storyId);
      const corpus = buildCorpusIndex(ctx.root, config.requirementsDir);
      const seeds = buildKeywordSeeds(input);
      const snapshot = captureReviewRunSnapshot(ctx.root, {
        storyId: args.storyId,
        storyPhase: story.phase,
      });
      const readiness = args.hosts === false
        ? []
        : (options.resolveReadiness ?? (() => probeReviewHostAvailability({
            storyId: args.storyId,
            materialHash: snapshot.materialHash,
            storyFilesHash: snapshot.storyFilesHash,
            cwd: ctx.root,
          }).hosts))();
      const hostResult = args.hosts === false
        ? { attempts: [], accepted: [], sanitizedDigest: '', hostDisagreement: false }
        : await collectHostKeywordProposals({
            storyId: args.storyId,
            payload: input,
            seeds,
            execute: withUnattendedReadiness(
              options.executeHost ?? productionExecutor(
                ctx,
                story.phase,
                typeof config.candidateSpecRouting?.hostStartupTimeoutMs === 'number' && config.candidateSpecRouting.hostStartupTimeoutMs > 0
                  ? config.candidateSpecRouting.hostStartupTimeoutMs
                  : DEFAULT_CANDIDATE_HOST_STARTUP_TIMEOUT_MS,
                typeof config.candidateSpecRouting?.hostTotalTimeoutMs === 'number' && config.candidateSpecRouting.hostTotalTimeoutMs > 0
                  ? config.candidateSpecRouting.hostTotalTimeoutMs
                  : DEFAULT_CANDIDATE_HOST_TOTAL_TIMEOUT_MS,
              ),
              readiness,
            ),
          });
      const artifact = routeCandidateSpecs({
        projectRoot: ctx.root,
        storyId: args.storyId,
        corpus,
        seeds,
        proposals: hostResult.accepted,
        hostDisagreement: hostResult.hostDisagreement,
        // Only structured Story riskSignals can trigger typed risk escalation.
        // Narrative title/description/checklist prose remains seed material, not authority.
        riskSignals: input.riskSignals ?? [],
        protectedSources: input.protectedSources,
        mode: config.candidateSpecRouting?.mode ?? 'shadow',
        candidateBudget: config.candidateSpecRouting?.candidateBudget,
        queryGroupBudget: config.candidateSpecRouting?.queryGroupBudget,
        rawHitsPerGroup: config.candidateSpecRouting?.rawHitsPerGroup,
        maxDocumentFrequencyRatio: config.candidateSpecRouting?.maxDocumentFrequencyRatio,
        forceFullScanReason: args.fullScanReason,
        storyInputDigest: digestCandidateRoutingValue(input),
        ...snapshot,
      });
      if (args.persist !== false) {
        ctx.store.writeCandidateSpecSet(args.storyId, artifact);
        autoCommitStoryMetadata(ctx.root, args.storyId, 'candidate_spec_route');
      }
      if (args.json || args.format === 'json') return artifact;
      return renderCandidateSpecRouteText(artifact, corpus.entries.length, hostResult.attempts, config.candidateSpecRouting?.mode ?? 'shadow');
    },
    candidate_spec_rollout_check(args: CandidateSpecRolloutCheckArgs) {
      if (!Array.isArray(args.windows)) throw new Error('candidate_spec_rollout_check.windows must be an array');
      const verdict = evaluateCandidateRoutingPromotion(args);
      if (args.json || args.format === 'json') return verdict;
      return [
        `Candidate routing rollout: ${args.from} -> ${args.to}`,
        `allowed=${verdict.allowed}`,
        `windows=${verdict.evaluatedWindowIds.join(',') || 'none'}`,
        `blockers=${verdict.blockers.join('; ') || 'none'}`,
        `rollback=${verdict.rollback}`,
        'corpusPromptInjectionAllowed=false',
      ].join('\n');
    },
